sibling_clipping_mask.example:
circle #avatarMask {
    at: (40px, 40px);
    size: 96px;
    clip: true; // Mask stencil
}
image #userPhoto {
    at: (40px, 40px);
    size: 96px 96px;
    src: "./assets/portrait.jpg";
}

overflow_clipping.example:
group #clippedCard {
    size: 400px 300px;
    radius: 20px;
    overflow: hidden; // Automatically clips nested children
    image #bg { size: 500px 400px; at: (-20px, -20px); src: "./landscape.jpg"; }
}
